find:
let before = snapshot
        for root in roots { _ = pages.update(root.id) { $0.place(one ? t : Self.share(of: root.transformBox, from: current, to: t)) } }
        record(name, before: before, coalescing: key)

replace:
for root in roots {
            let before = snapshot
            _ = pages.update(root.id) { $0.place(one ? t : Self.share(of: root.transformBox, from: current, to: t)) }
            record(name, before: before, coalescing: nil)
        }
